@EnabledIfEnvironmentVariable(named = "MISTRAL_AI_API_KEY", matches = ".*")
class PaymentStatusBeanIT {

    // Assuming we have the following data
    public static final Map<String, StatusDate> DATA = Map.of("T1001", new StatusDate("Paid", "2021-10-05"), "T1002", new StatusDate("Unpaid", "2021-10-06"), "T1003", new StatusDate("Paid", "2021-10-07"), "T1004", new StatusDate("Paid", "2021-10-05"), "T1005", new StatusDate("Pending", "2021-10-08"));

    private final Logger logger = LoggerFactory.getLogger(PaymentStatusBeanIT.class);

    private final ApplicationContextRunner contextRunner = new ApplicationContextRunner().withPropertyValues("spring.ai.mistralai.apiKey=" + System.getenv("MISTRAL_AI_API_KEY")).withConfiguration(SpringAiTestAutoConfigurations.of(MistralAiChatAutoConfiguration.class)).withUserConfiguration(Config.class);

    @Test
    void functionCallTest() {
        this.contextRunner.withPropertyValues("spring.ai.mistralai.chat.options.model=" + MistralAiApi.ChatModel.LARGE.getValue()).run(context -> {
            MistralAiChatModel chatModel = context.getBean(MistralAiChatModel.class);
            ChatResponse response = chatModel.call(new Prompt(List.of(new UserMessage("What's the status of my transaction with id T1001?")), MistralAiChatOptions.builder().toolNames("retrievePaymentStatus").toolNames("retrievePaymentDate").build()));
            logger.info("Response: {}", response);
            assertThat(response.getResult().getOutput().getText()).containsIgnoringCase("T1001");
            assertThat(response.getResult().getOutput().getText()).containsIgnoringCase("paid");
        });
    }

    record StatusDate(String status, String date) {
    }

    @Configuration
    static class Config {

        @Bean
        @Description("Get payment status of a transaction")
        public Function<Transaction, Status> retrievePaymentStatus() {
            return transaction -> new Status(DATA.get(transaction.transactionId).status());
        }

        @Bean
        @Description("Get payment date of a transaction")
        public Function<Transaction, Date> retrievePaymentDate() {
            return transaction -> new Date(DATA.get(transaction.transactionId).date());
        }

        public record Transaction(@JsonProperty(required = true, value = "transaction_id") String transactionId) {
        }

        public record Status(@JsonProperty(required = true, value = "status") String status) {
        }

        public record Date(@JsonProperty(required = true, value = "date") String date) {
        }
    }
}
