The <a href="https://github.com/spring-projects/spring-ai/blob/main/models/spring-ai-mistral-ai/src/main/java/org/springframework/ai/mistralai/MistralAiChatModel.java">MistralAiChatModel</a> implements the <code>ChatModel</code> and <code>StreamingChatModel</code> and uses the <a href="#low-level-api">Low-level MistralAiApi Client</a> to connect to the Mistral AI service.

Add the <code>spring-ai-mistral-ai</code> dependency to your project&#8217;s Maven <code>pom.xml</code> file:

&lt;dependency&gt;
    &lt;groupId&gt;org.springframework.ai&lt;/groupId&gt;
    &lt;artifactId&gt;spring-ai-mistral-ai&lt;/artifactId&gt;
&lt;/dependency&gt;

or to your Gradle <code>build.gradle</code> build file.

dependencies {
    implementation 'org.springframework.ai:spring-ai-mistral-ai'
}

Refer to the <a href="getting-started.html#dependency-management">Dependency Management</a> section to add the Spring AI BOM to your build file.

Next, create a <code>MistralAiChatModel</code> and use it for text generations:

var mistralAiApi = new MistralAiApi(System.getenv("MISTRAL_AI_API_KEY"));

var chatModel = new MistralAiChatModel(this.mistralAiApi, MistralAiChatOptions.builder()
                .model(MistralAiApi.ChatModel.LARGE.getValue())
                .temperature(0.4)
                .maxTokens(200)
                .build());

ChatResponse response = this.chatModel.call(
    new Prompt("Generate the names of 5 famous pirates."));

// Or with streaming responses
Flux&lt;ChatResponse&gt; response = this.chatModel.stream(
    new Prompt("Generate the names of 5 famous pirates."));

The <code>MistralAiChatOptions</code> provides the configuration information for the chat requests.
The <code>MistralAiChatOptions.Builder</code> is a fluent options-builder.
---
/**
 * Represents a Mistral AI Chat Model.
 *
 * @author Ricken Bazolo
 * @author Christian Tzolov
 * @author Grogdunn
 * @author Thomas Vitale
 * @author luocongqiu
 * @author Ilayaperumal Gopinathan
 * @author Alexandros Pappas
 * @author Nicolas Krier
 * @author Jason Smith
 * @since 1.0.0
 */
public class MistralAiChatModel implements ChatModel {

    private static final ChatModelObservationConvention DEFAULT_OBSERVATION_CONVENTION = new DefaultChatModelObservationConvention();

    private static final ToolCallingManager DEFAULT_TOOL_CALLING_MANAGER = ToolCallingManager.builder().build();

    private final Logger logger = LoggerFactory.getLogger(getClass());

    /**
     * The default options used for the chat completion requests.
     */
    private final MistralAiChatOptions defaultOptions;

    /**
     * Low-level access to the Mistral API.
     */
    private final MistralAiApi mistralAiApi;

    private final RetryTemplate retryTemplate;

    /**
     * Observation registry used for instrumentation.
     */
    private final ObservationRegistry observationRegistry;

    private final ToolCallingManager toolCallingManager;

    /**
     * The tool execution eligibility predicate used to determine if a tool can be
     * executed.
     */
    private final ToolExecutionEligibilityPredicate toolExecutionEligibilityPredicate;

    /**
     * Conventions to use for generating observations.
     */
    private ChatModelObservationConvention observationConvention = DEFAULT_OBSERVATION_CONVENTION;

    public MistralAiChatModel(MistralAiApi mistralAiApi, MistralAiChatOptions defaultOptions, ToolCallingManager toolCallingManager, RetryTemplate retryTemplate, ObservationRegistry observationRegistry, ToolExecutionEligibilityPredicate toolExecutionEligibilityPredicate) {
        Assert.notNull(mistralAiApi, "mistralAiApi cannot be null");
        Assert.notNull(defaultOptions, "defaultOptions cannot be null");
        Assert.notNull(toolCallingManager, "toolCallingManager cannot be null");
        Assert.notNull(retryTemplate, "retryTemplate cannot be null");
        Assert.notNull(observationRegistry, "observationRegistry cannot be null");
        Assert.notNull(toolExecutionEligibilityPredicate, "toolExecutionEligibilityPredicate cannot be null");
        this.mistralAiApi = mistralAiApi;
        this.defaultOptions = defaultOptions;
        this.toolCallingManager = toolCallingManager;
        this.retryTemplate = retryTemplate;
        this.observationRegistry = observationRegistry;
        this.toolExecutionEligibilityPredicate = toolExecutionEligibilityPredicate;
    }

    public static ChatResponseMetadata from(MistralAiApi.ChatCompletion result) {
        Assert.notNull(result, "Mistral AI ChatCompletion must not be null");
        DefaultUsage usage = getDefaultUsage(result.usage());
        return ChatResponseMetadata.builder().id(result.id()).model(result.model()).usage(usage).keyValue("created", result.created()).build();
    }

    public static ChatResponseMetadata from(MistralAiApi.ChatCompletion result, Usage usage) {
        Assert.notNull(result, "Mistral AI ChatCompletion must not be null");
        return ChatResponseMetadata.builder().id(result.id()).model(result.model()).usage(usage).keyValue("created", result.created()).build();
    }

    private static DefaultUsage getDefaultUsage(MistralAiApi.Usage usage) {
        return new DefaultUsage(usage.promptTokens(), usage.completionTokens(), usage.totalTokens(), usage);
    }

    @Override
    public ChatResponse call(Prompt prompt) {
        // Before moving any further, build the final request Prompt,
        // merging runtime and default options.
        Prompt requestPrompt = buildRequestPrompt(prompt);
        return this.internalCall(requestPrompt, null);
    }

    public ChatResponse internalCall(Prompt prompt, ChatResponse previousChatResponse) {
        MistralAiApi.ChatCompletionRequest request = createRequest(prompt, false);
        ChatModelObservationContext observationContext = ChatModelObservationContext.builder().prompt(prompt).provider(MistralAiApi.PROVIDER_NAME).build();
        ChatResponse response = ChatModelObservationDocumentation.CHAT_MODEL_OPERATION.observation(this.observationConvention, DEFAULT_OBSERVATION_CONVENTION, () -> observationContext, this.observationRegistry).observe(() -> {
            ResponseEntity<ChatCompletion> completionEntity = RetryUtils.execute(this.retryTemplate, () -> this.mistralAiApi.chatCompletionEntity(request));
            ChatCompletion chatCompletion = completionEntity.getBody();
            if (chatCompletion == null) {
                logger.warn("No chat completion returned for prompt: {}", prompt);
                return new ChatResponse(List.of());
            }
            List<Generation> generations = chatCompletion.choices().stream().map(choice -> {
                // @formatter:off
                Map<String, Object> metadata = Map.of("id", chatCompletion.id() != null ? chatCompletion.id() : "", "index", choice.index(), "role", choice.message().role() != null ? choice.message().role().name() : "", "finishReason", choice.finishReason() != null ? choice.finishReason().name() : "");
                // @formatter:on
                return buildGeneration(choice, metadata);
            }).toList();
            DefaultUsage usage = getDefaultUsage(completionEntity.getBody().usage());
            Usage cumulativeUsage = UsageCalculator.getCumulativeUsage(usage, previousChatResponse);
            ChatResponse chatResponse = new ChatResponse(generations, from(completionEntity.getBody(), cumulativeUsage));
            observationContext.setResponse(chatResponse);
            return chatResponse;
        });
        if (this.toolExecutionEligibilityPredicate.isToolExecutionRequired(prompt.getOptions(), response)) {
            var toolExecutionResult = this.toolCallingManager.executeToolCalls(prompt, response);
            if (toolExecutionResult.returnDirect()) {
                // Return tool execution result directly to the client.
                return ChatResponse.builder().from(response).generations(ToolExecutionResult.buildGenerations(toolExecutionResult)).build();
            } else {
                // Send the tool execution result back to the model.
                return this.internalCall(new Prompt(toolExecutionResult.conversationHistory(), prompt.getOptions()), response);
            }
        }
        return response;
    }

    @Override
    public Flux<ChatResponse> stream(Prompt prompt) {
        // Before moving any further, build the final request Prompt,
        // merging runtime and default options.
        Prompt requestPrompt = buildRequestPrompt(prompt);
        return this.internalStream(requestPrompt, null);
    }

    public Flux<ChatResponse> internalStream(Prompt prompt, ChatResponse previousChatResponse) {
        return Flux.deferContextual(contextView -> {
            var request = createRequest(prompt, true);
            ChatModelObservationContext observationContext = ChatModelObservationContext.builder().prompt(prompt).provider(MistralAiApi.PROVIDER_NAME).build();
            Observation observation = ChatModelObservationDocumentation.CHAT_MODEL_OPERATION.observation(this.observationConvention, DEFAULT_OBSERVATION_CONVENTION, () -> observationContext, this.observationRegistry);
            observation.parentObservation(contextView.getOrDefault(ObservationThreadLocalAccessor.KEY, null)).start();
            Flux<ChatCompletionChunk> completionChunks = RetryUtils.execute(this.retryTemplate, () -> this.mistralAiApi.chatCompletionStream(request));
            // For chunked responses, only the first chunk contains the choice role.
            // The rest of the chunks with same ID share the same role.
            ConcurrentHashMap<String, String> roleMap = new ConcurrentHashMap<>();
            // Convert the ChatCompletionChunk into a ChatCompletion to be able to reuse
            // the function call handling logic.
            Flux<ChatResponse> chatResponse = completionChunks.map(this::toChatCompletion).switchMap(chatCompletion -> Mono.just(chatCompletion).map(chatCompletion2 -> {
                try {
                    @SuppressWarnings("null")
                    String id = chatCompletion2.id();
                    // @formatter:off
                    List<Generation> generations = chatCompletion2.choices().stream().map(choice -> {
                        if (choice.message().role() != null) {
                            roleMap.putIfAbsent(id, choice.message().role().name());
                        }
                        Map<String, Object> metadata = Map.of("id", chatCompletion2.id(), "role", roleMap.getOrDefault(id, ""), "index", choice.index(), "finishReason", choice.finishReason() != null ? choice.finishReason().name() : "");
                        return buildGeneration(choice, metadata);
                    }).toList();
                    // @formatter:on
                    if (chatCompletion2.usage() != null) {
                        DefaultUsage usage = getDefaultUsage(chatCompletion2.usage());
                        Usage cumulativeUsage = UsageCalculator.getCumulativeUsage(usage, previousChatResponse);
                        return new ChatResponse(generations, from(chatCompletion2, cumulativeUsage));
                    } else {
                        return new ChatResponse(generations);
                    }
                } catch (Exception e) {
                    logger.error("Error processing chat completion", e);
                    return new ChatResponse(List.of());
                }
            }));
            // @formatter:off
            Flux<ChatResponse> chatResponseFlux = chatResponse.flatMap(response -> {
                if (this.toolExecutionEligibilityPredicate.isToolExecutionRequired(prompt.getOptions(), response)) {
                    // FIXME: bounded elastic needs to be used since tool calling
                    //  is currently only synchronous
                    return Flux.deferContextual(ctx -> {
                        ToolExecutionResult toolExecutionResult;
                        try {
                            ToolCallReactiveContextHolder.setContext(ctx);
                            toolExecutionResult = this.toolCallingManager.executeToolCalls(prompt, response);
                        } finally {
                            ToolCallReactiveContextHolder.clearContext();
                        }
                        if (toolExecutionResult.returnDirect()) {
                            // Return tool execution result directly to the client.
                            return Flux.just(ChatResponse.builder().from(response).generations(ToolExecutionResult.buildGenerations(toolExecutionResult)).build());
                        } else {
                            // Send the tool execution result back to the model.
                            return this.internalStream(new Prompt(toolExecutionResult.conversationHistory(), prompt.getOptions()), response);
                        }
                    }).subscribeOn(Schedulers.boundedElastic());
                } else {
                    return Flux.just(response);
                }
            }).doOnError(observation::error).doFinally(s -> observation.stop()).contextWrite(ctx -> ctx.put(ObservationThreadLocalAccessor.KEY, observation));
            // @formatter:on;
            return new MessageAggregator().aggregate(chatResponseFlux, observationContext::setResponse);
        });
    }

    private Generation buildGeneration(Choice choice, Map<String, Object> metadata) {
        List<AssistantMessage.ToolCall> toolCalls = choice.message().toolCalls() == null ? List.of() : choice.message().toolCalls().stream().map(toolCall -> new AssistantMessage.ToolCall(toolCall.id(), "function", toolCall.function().name(), toolCall.function().arguments())).toList();
        var assistantMessage = AssistantMessage.builder().content(choice.message().content()).properties(metadata).toolCalls(toolCalls).build();
        String finishReason = (choice.finishReason() != null ? choice.finishReason().name() : "");
        var generationMetadata = ChatGenerationMetadata.builder().finishReason(finishReason).build();
        return new Generation(assistantMessage, generationMetadata);
    }

    private ChatCompletion toChatCompletion(ChatCompletionChunk chunk) {
        List<Choice> choices = chunk.choices().stream().map(cc -> new Choice(cc.index(), cc.delta(), cc.finishReason(), cc.logprobs())).toList();
        return new ChatCompletion(chunk.id(), "chat.completion", chunk.created(), chunk.model(), choices, chunk.usage());
    }

    Prompt buildRequestPrompt(Prompt prompt) {
        // Process runtime options
        MistralAiChatOptions runtimeOptions = null;
        if (prompt.getOptions() != null) {
            if (prompt.getOptions() instanceof ToolCallingChatOptions toolCallingChatOptions) {
                runtimeOptions = ModelOptionsUtils.copyToTarget(toolCallingChatOptions, ToolCallingChatOptions.class, MistralAiChatOptions.class);
            } else {
                runtimeOptions = ModelOptionsUtils.copyToTarget(prompt.getOptions(), ChatOptions.class, MistralAiChatOptions.class);
            }
        }
        // Define request options by merging runtime options and default options
        MistralAiChatOptions requestOptions = ModelOptionsUtils.merge(runtimeOptions, this.defaultOptions, MistralAiChatOptions.class);
        // Merge @JsonIgnore-annotated options explicitly since they are ignored by
        // Jackson, used by ModelOptionsUtils.
        if (runtimeOptions != null) {
            requestOptions.setInternalToolExecutionEnabled(ModelOptionsUtils.mergeOption(runtimeOptions.getInternalToolExecutionEnabled(), this.defaultOptions.getInternalToolExecutionEnabled()));
            requestOptions.setToolNames(ToolCallingChatOptions.mergeToolNames(runtimeOptions.getToolNames(), this.defaultOptions.getToolNames()));
            requestOptions.setToolCallbacks(ToolCallingChatOptions.mergeToolCallbacks(runtimeOptions.getToolCallbacks(), this.defaultOptions.getToolCallbacks()));
            requestOptions.setToolContext(ToolCallingChatOptions.mergeToolContext(runtimeOptions.getToolContext(), this.defaultOptions.getToolContext()));
        } else {
            requestOptions.setInternalToolExecutionEnabled(this.defaultOptions.getInternalToolExecutionEnabled());
            requestOptions.setToolNames(this.defaultOptions.getToolNames());
            requestOptions.setToolCallbacks(this.defaultOptions.getToolCallbacks());
            requestOptions.setToolContext(this.defaultOptions.getToolContext());
        }
        ToolCallingChatOptions.validateToolCallbacks(requestOptions.getToolCallbacks());
        return new Prompt(prompt.getInstructions(), requestOptions);
    }

    /**
     * Accessible for testing.
     */
    MistralAiApi.ChatCompletionRequest createRequest(Prompt prompt, boolean stream) {
        // @formatter:off
        List<ChatCompletionMessage> chatCompletionMessages = prompt.getInstructions().stream().flatMap(this::createChatCompletionMessages).toList();
        // @formatter:on
        var request = new MistralAiApi.ChatCompletionRequest(chatCompletionMessages, stream);
        MistralAiChatOptions requestOptions = (MistralAiChatOptions) prompt.getOptions();
        request = ModelOptionsUtils.merge(requestOptions, request, MistralAiApi.ChatCompletionRequest.class);
        // Add the tool definitions to the request's tools parameter.
        List<ToolDefinition> toolDefinitions = this.toolCallingManager.resolveToolDefinitions(requestOptions);
        if (!CollectionUtils.isEmpty(toolDefinitions)) {
            request = ModelOptionsUtils.merge(MistralAiChatOptions.builder().tools(this.getFunctionTools(toolDefinitions)).build(), request, ChatCompletionRequest.class);
        }
        return request;
    }

    private Stream<ChatCompletionMessage> createChatCompletionMessages(Message message) {
        return switch(message.getMessageType()) {
            case USER ->
                Stream.of(createUserChatCompletionMessage(message));
            case SYSTEM ->
                Stream.of(createSystemChatCompletionMessage(message));
            case ASSISTANT ->
                Stream.of(createAssistantChatCompletionMessage(message));
            case TOOL ->
                createToolChatCompletionMessages(message);
            default ->
                throw new IllegalStateException("Unknown message type: " + message.getMessageType());
        };
    }

    private Stream<ChatCompletionMessage> createToolChatCompletionMessages(Message message) {
        if (message instanceof ToolResponseMessage toolResponseMessage) {
            var chatCompletionMessages = new ArrayList<ChatCompletionMessage>();
            for (ToolResponseMessage.ToolResponse toolResponse : toolResponseMessage.getResponses()) {
                Assert.isTrue(toolResponse.id() != null, "ToolResponseMessage.ToolResponse must have an id.");
                var chatCompletionMessage = new ChatCompletionMessage(toolResponse.responseData(), ChatCompletionMessage.Role.TOOL, toolResponse.name(), null, toolResponse.id());
                chatCompletionMessages.add(chatCompletionMessage);
            }
            return chatCompletionMessages.stream();
        } else {
            throw new IllegalArgumentException("Unsupported tool message class: " + message.getClass().getName());
        }
    }

    private ChatCompletionMessage createAssistantChatCompletionMessage(Message message) {
        if (message instanceof AssistantMessage assistantMessage) {
            List<ToolCall> toolCalls = null;
            if (!CollectionUtils.isEmpty(assistantMessage.getToolCalls())) {
                toolCalls = assistantMessage.getToolCalls().stream().map(this::mapToolCall).toList();
            }
            return new ChatCompletionMessage(assistantMessage.getText(), ChatCompletionMessage.Role.ASSISTANT, null, toolCalls, null);
        } else {
            throw new IllegalArgumentException("Unsupported assistant message class: " + message.getClass().getName());
        }
    }

    private ChatCompletionMessage createSystemChatCompletionMessage(Message message) {
        return new ChatCompletionMessage(message.getText(), ChatCompletionMessage.Role.SYSTEM);
    }

    private ChatCompletionMessage createUserChatCompletionMessage(Message message) {
        Object content = message.getText();
        if (message instanceof UserMessage userMessage && !CollectionUtils.isEmpty(userMessage.getMedia())) {
            List<ChatCompletionMessage.MediaContent> contentList = new ArrayList<>(List.of(new ChatCompletionMessage.MediaContent(message.getText())));
            contentList.addAll(userMessage.getMedia().stream().map(this::mapToMediaContent).toList());
            content = contentList;
        }
        return new ChatCompletionMessage(content, ChatCompletionMessage.Role.USER);
    }

    private ToolCall mapToolCall(AssistantMessage.ToolCall toolCall) {
        var function = new ChatCompletionFunction(toolCall.name(), toolCall.arguments());
        return new ToolCall(toolCall.id(), toolCall.type(), function, null);
    }

    private ChatCompletionMessage.MediaContent mapToMediaContent(Media media) {
        return new ChatCompletionMessage.MediaContent(new ChatCompletionMessage.MediaContent.ImageUrl(this.fromMediaData(media.getMimeType(), media.getData())));
    }

    private String fromMediaData(MimeType mimeType, Object mediaContentData) {
        if (mediaContentData instanceof byte[] bytes) {
            // Assume the bytes are an image. So, convert the bytes to a base64 encoded
            // following the prefix pattern.
            return String.format("data:%s;base64,%s", mimeType.toString(), Base64.getEncoder().encodeToString(bytes));
        } else if (mediaContentData instanceof String text) {
            // Assume the text is a URLs or a base64 encoded image prefixed by the user.
            return text;
        } else {
            throw new IllegalArgumentException("Unsupported media data type: " + mediaContentData.getClass().getSimpleName());
        }
    }

    private List<MistralAiApi.FunctionTool> getFunctionTools(List<ToolDefinition> toolDefinitions) {
        return toolDefinitions.stream().map(toolDefinition -> {
            var function = new MistralAiApi.FunctionTool.Function(toolDefinition.description(), toolDefinition.name(), toolDefinition.inputSchema());
            return new MistralAiApi.FunctionTool(function);
        }).toList();
    }

    @Override
    public ChatOptions getDefaultOptions() {
        return MistralAiChatOptions.fromOptions(this.defaultOptions);
    }

    /**
     * Use the provided convention for reporting observation data
     * @param observationConvention The provided convention
     */
    public void setObservationConvention(ChatModelObservationConvention observationConvention) {
        Assert.notNull(observationConvention, "observationConvention cannot be null");
        this.observationConvention = observationConvention;
    }

    public static Builder builder() {
        return new Builder();
    }

    public static final class Builder {

        private MistralAiApi mistralAiApi;

        private MistralAiChatOptions defaultOptions = MistralAiChatOptions.builder().temperature(0.7).topP(1.0).safePrompt(false).model(MistralAiApi.ChatModel.SMALL.getValue()).build();

        private ToolCallingManager toolCallingManager = DEFAULT_TOOL_CALLING_MANAGER;

        private ToolExecutionEligibilityPredicate toolExecutionEligibilityPredicate = new DefaultToolExecutionEligibilityPredicate();

        private RetryTemplate retryTemplate = RetryUtils.DEFAULT_RETRY_TEMPLATE;

        private ObservationRegistry observationRegistry = ObservationRegistry.NOOP;

        private Builder() {
        }

        public Builder mistralAiApi(MistralAiApi mistralAiApi) {
            this.mistralAiApi = mistralAiApi;
            return this;
        }

        public Builder defaultOptions(MistralAiChatOptions defaultOptions) {
            this.defaultOptions = defaultOptions;
            return this;
        }

        public Builder toolCallingManager(ToolCallingManager toolCallingManager) {
            this.toolCallingManager = toolCallingManager;
            return this;
        }

        public Builder toolExecutionEligibilityPredicate(ToolExecutionEligibilityPredicate toolExecutionEligibilityPredicate) {
            this.toolExecutionEligibilityPredicate = toolExecutionEligibilityPredicate;
            return this;
        }

        public Builder retryTemplate(RetryTemplate retryTemplate) {
            this.retryTemplate = retryTemplate;
            return this;
        }

        public Builder observationRegistry(ObservationRegistry observationRegistry) {
            this.observationRegistry = observationRegistry;
            return this;
        }

        public MistralAiChatModel build() {
            return new MistralAiChatModel(this.mistralAiApi, this.defaultOptions, this.toolCallingManager, this.retryTemplate, this.observationRegistry, this.toolExecutionEligibilityPredicate);
        }
    }
}
